for (const [key, fr, en] of [...phaseThreeRows, ...englishFallbackRows]) {
  rows.push([key, fr, en, ...Array(localeOrder.length - 2).fill(en)]);
}

export const appMessages = Object.fromEntries(
  localeOrder.map((locale, localeIndex) => [
    locale,
    Object.fromEntries(rows.map(([key, ...values]) => [key, values[localeIndex]])),
  ]),
);
